'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var log1p = require( '@stdlib/math/base/special/log1p' );
var ln = require( '@stdlib/math/base/special/ln' );
var pow = require( '@stdlib/math/base/special/pow' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution.
*
* @param {PositiveNumber} alpha - scale parameter
* @param {PositiveNumber} beta - shape parameter
* @returns {Function} logCDF
*
* @example
* var logcdf = factory( 1.0, 1.0 );
* var y = logcdf( 2.0 );
* // returns ~-0.405
*
* y = logcdf( -1.0 );
* // returns -Infinity
*/
function factory( alpha, beta ) {
	if (
		isnan( alpha ) ||
		isnan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0
	) {
		return constantFunction( NaN );
	}
	return logcdf;

	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a log-logistic distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated logCDF
	*/
	function logcdf( x ) {
		var base;
		var xb;
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x <= 0.0 ) {
			return NINF;
		}
		// Select the algebraically equivalent form which keeps the intermediate power bounded, thus avoiding overflow to infinity as `x` grows large, while preserving accuracy in the lower tail...
		if ( x <= alpha ) {
			base = x / alpha;
			xb = pow( base, beta );
			return ( beta * ln( base ) ) - log1p( xb );
		}
		return -log1p( pow( alpha / x, beta ) );
	}
}


// EXPORTS //

module.exports = factory;
